import { createDecipheriv, createHmac } from "node:crypto";
const payload={"iv":"l4qdVhQVfHj8SemQ","tag":"isW82N47olkDriB7NEHJmA==","data":""};
export function getJournalTemplate(): string {
 const key=process.env.RAUHNAECHTE_JOURNAL_CONTENT_KEY ? Buffer.from(process.env.RAUHNAECHTE_JOURNAL_CONTENT_KEY,"hex") : createHmac("sha256",process.env.JWT_SECRET || "").update("journal-content-encryption-v1").digest();
 const decipher=createDecipheriv("aes-256-gcm",key,Buffer.from(payload.iv,"base64"));
 decipher.setAuthTag(Buffer.from(payload.tag,"base64"));
 return Buffer.concat([decipher.update(Buffer.from(payload.data,"base64")),decipher.final()]).toString("utf8");
}
